arguments.content:
"""Offline validator for a candidate rack layout (no API calls).

Usage: python3 -I check_layout.py layout.json
layout.json: {"assignments": [{rack, bay, shift, team, rdma, priority_iops}, ...]}
"""
import json
import sys

RACKS = {
    "R0": dict(spine="Spine-A", zone="Zone-A", rdma=False, cap=24.0),
    "R1": dict(spine="Spine-A", zone="Zone-A", rdma=False, cap=22.0),
    "R2": dict(spine="Spine-A", zone="Zone-A", rdma=False, cap=22.0),
    "R3": dict(spine="Spine-A", zone="Zone-B", rdma=False, cap=20.0),
    "R4": dict(spine="Spine-B", zone="Zone-B", rdma=True, cap=22.0),
    "R5": dict(spine="Spine-B", zone="Zone-B", rdma=True, cap=24.0),
}
TDP = {"T1": 5.5, "T2": 4.2, "T3": 5.5, "T4": 4.2, "T5": 3.0, "T6": 5.5,
       "PROD-ONLINE-INFERENCE": 0.0}
HIGH = {"T1", "T3", "T6"}
HIGH_IO = {"T2", "T4"}
PO = {"T1": 35000, "T2": 32000, "T3": 26000, "T4": 20000, "T5": 18000, "T6": 22000}
# negotiated terms: (bays, shift)
NEED = {"T1": (4, "24H"), "T2": (4, "24H"), "T3": (3, "24H"),
        "T4": (4, "NIGHT_ONLY"), "T5": (4, "DAY_ONLY"), "T6": (3, "24H")}
BASE = {"24H": 6200, "DAY_ONLY": 3800, "NIGHT_ONLY": 2400}
WINDOWS = {"24H": ("DAY", "NIGHT"), "DAY_ONLY": ("DAY",), "NIGHT_ONLY": ("NIGHT",)}
R0_EXPECTED = [("R0", b, "24H", "PROD-ONLINE-INFERENCE", False, False) for b in range(4)]


def main(path):
    items = json.load(open(path))["assignments"]
    errs, warns = [], []

    r0 = sorted((a["rack"], a["bay"], a["shift"], a["team"], bool(a.get("rdma")),
                 bool(a.get("priority_iops"))) for a in items if a["rack"] == "R0")
    if r0 != R0_EXPECTED:
        errs.append(f"R0 changed: {r0}")

    # slot occupancy per (rack, bay, window)
    occ = {}
    for a in items:
        for w in WINDOWS[a["shift"]]:
            k = (a["rack"], a["bay"], w)
            if k in occ:
                errs.append(f"slot conflict {k}: {occ[k]} vs {a['team']}")
            occ[k] = a["team"]

    # power per rack per window
    for r, meta in RACKS.items():
        for w in ("DAY", "NIGHT"):
            kw = sum(TDP[occ[(r, b, w)]] for b in range(4) if (r, b, w) in occ)
            flag = "OVER" if kw > meta["cap"] + 1e-9 else "ok"
            print(f"  power {r} {w:5s} {kw:5.1f}/{meta['cap']:.0f} kW {flag}")
            if flag == "OVER":
                errs.append(f"power over cap {r} {w} {kw}")

    # thermal: vertically adjacent HIGH bays in same window
    for r in RACKS:
        for w in ("DAY", "NIGHT"):
            for b in range(3):
                lo, hi = occ.get((r, b, w)), occ.get((r, b + 1, w))
                if lo in HIGH and hi in HIGH:
                    errs.append(f"HIGH-HIGH adjacency {r} bay{b}/{b+1} {w}: {lo},{hi}")

    # IO: T2 must not share a rack with another high-IO team
    for r in RACKS:
        teams = {a["team"] for a in items if a["rack"] == r}
        if "T2" in teams and (teams & HIGH_IO) - {"T2"}:
            errs.append(f"T2 shares {r} with high-IO {(teams & HIGH_IO) - {'T2'}}")

    # per-team checks and cost
    total = 0.0
    for t, (n, shift) in NEED.items():
        mine = [a for a in items if a["team"] == t]
        cost = 0.0
        for a in mine:
            meta = RACKS[a["rack"]]
            c = BASE[a["shift"]]
            if a.get("rdma"):
                if not meta["rdma"]:
                    errs.append(f"{t} rdma flag on non-RDMA rack {a['rack']}")
                c += 400
            if t == "T2" and meta["zone"] == "Zone-B":
                c += 4000
            cost += c
        total += cost
        racks = sorted({a["rack"] for a in mine})
        spines = {RACKS[r]["spine"] for r in racks}
        if len(mine) != n:
            errs.append(f"{t} has {len(mine)} bays, needs {n}")
        if any(a["shift"] != shift for a in mine):
            errs.append(f"{t} shift mismatch, needs {shift}")
        if cost > PO[t]:
            errs.append(f"{t} cost {cost} > PO {PO[t]}")
        if t == "T1" and not all(a["rack"] in ("R4", "R5") and a.get("rdma") for a in mine):
            errs.append("T1 must be on R4/R5 with rdma")
        if t == "T2" and not all(a["rack"] in ("R1", "R2") for a in mine):
            errs.append("T2 must be in Zone-A R1/R2")
        if t == "T3" and len(spines) != 1:
            errs.append(f"T3 crosses spines {spines}")
        if t == "T4" and not all(a.get("priority_iops") for a in mine):
            errs.append("T4 needs priority_iops on all bays")
        print(f"  {t}: bays={len(mine)} racks={racks} spines={sorted(spines)} cost=${cost:,.0f} (PO ${PO[t]:,})")
    print(f"  TOTAL ${total:,.0f} / $138,000")
    if total > 138000:
        errs.append("total over budget cap")

    for e in errs:
        print("ERROR:", e)
    print("RESULT:", "PASS" if not errs else f"FAIL ({len(errs)})")
    return 0 if not errs else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1]))

